from build import build
S={
'periorbita':'The <b>fibrous cone</b> around the eye muscles, nerves and vessels, open toward the orbital fissure.',
'lacrimal gland':'Sits <b>dorsolateral to the eyeball</b>, under the orbital ligament, inside the periorbita. It makes most of the tear film.',
'levator palpebrae superioris':'A thin muscle on the <b>dorsal surface of the dorsal rectus</b> that lifts the upper eyelid (CN III). Easy to destroy.',
'obliquus muscles':'The 2 oblique eye muscles: <b>dorsal oblique</b> (CN IV) and <b>ventral oblique</b> (CN III).',
'rectus muscles':'The 4 recti (<b>dorsal, medial, ventral, lateral</b>) run from around the optic canal to the sclera. Lateral rectus = CN VI; the rest = CN III.',
'retractor bulbi':'The cone of muscle <b>right around the optic nerve</b> that pulls the eye back (CN VI).',
'dorsal rectus':'Rotates the eye <b>up</b>. Nerve: <b>CN III</b>.',
'medial rectus':'Rotates the eye <b>medially</b> (toward the nose). Nerve: <b>CN III</b>.',
'ventral rectus':'Rotates the eye <b>down</b>. Nerve: <b>CN III</b>.',
'lateral rectus':'Rotates the eye <b>laterally</b>. Nerve: <b>CN VI</b> ("LR6"). Don\'t cut it in lab.',
'dorsal oblique':'Its tendon runs through the <b>trochlea</b>, then turns laterally onto the eyeball. It rotates the top of the eye medially. Nerve: <b>CN IV</b>.',
'trochlea':'The <b>cartilage pulley</b> on the medial orbit wall that the dorsal oblique tendon slides through.',
'ventral oblique':'The only eye muscle that <b>doesn\'t start at the back of the orbit</b>; it starts on the medial orbit wall near the lacrimal fossa. Nerve: <b>CN III</b>.',
'superficial gland of the third eyelid':'Wraps the <b>base of the third-eyelid cartilage</b>. When it prolapses, that\'s "cherry eye."',
'external fibrous coat':'The <b>outer tunic</b> of the eyeball = <b>cornea + sclera</b>.',
'cornea':'The <b>clear front</b> of the fibrous coat. No blood vessels.',
'sclera':'The <b>white, opaque</b> back part of the fibrous coat, where the eye muscles insert.',
'limbus':'The <b>junction of the cornea and sclera</b>.',
'middle vascular coat':'The middle tunic = the <b>uvea</b>: iris + ciliary body + choroid.',
'uvea':'Another name for the <b>middle vascular coat</b> (iris, ciliary body, choroid).',
'iris':'The colored diaphragm in front of the lens. Its opening is the <b>pupil</b>.',
'pupil':'The opening in the iris. <b>Dilator pupillae</b> (sympathetic) widens it; sphincter (parasympathetic) narrows it.',
'choroid':'The vascular layer between the <b>sclera and retina</b> at the back of the eye; it holds the tapetum.',
'ora serrata':'The jagged line where the <b>light-sensitive retina ends</b> and the ciliary part begins.',
'fundus':'The <b>back of the eye</b> you see with an ophthalmoscope (retina, optic disk, tapetum).',
'tapetum lucidum':'The <b>reflective layer in the dorsal choroid</b> that makes dogs\' eyes shine at night.',
'ciliary body':'The uvea ring between the iris and choroid. Its muscle changes lens shape, and its processes make <b>aqueous humor</b>.',
'ciliary processes':'The folds of the ciliary body that <b>secrete aqueous humor</b> and anchor the zonular fibers.',
'zonule':'The <b>suspensory ligament</b> of the lens (all the zonular fibers together).',
'zonular fibers':'Fibers from the <b>ciliary processes to the lens equator</b> that hold the lens in place.',
'lens':'A clear disc behind the iris, held by the zonule: <b>capsule, soft cortex, hard nucleus</b>.',
'vitreous body':'The <b>clear gel</b> that fills the vitreous chamber behind the lens.',
'vitreous chamber':'The big space <b>behind the lens</b>, filled by the vitreous body.',
'aqueous humor':'Made by the ciliary processes. It flows <b>posterior chamber → pupil → anterior chamber → iridocorneal angle</b>.',
'anterior chamber':'The space between the <b>cornea and iris</b>.',
'posterior chamber':'The thin space between the <b>iris and lens</b>. It is NOT behind the lens.',
'iridocorneal angle':'The angle between the <b>iris and cornea</b>, where aqueous humor drains (blocked in glaucoma).',
'scleral sinus':'The venous channel in the sclera near the angle that <b>carries aqueous humor away</b>.',
'pectinate ligament':'Strands spanning the <b>iridocorneal angle</b> from the iris base to the cornea.',
'internal coat':'The inner tunic of the eyeball = the <b>retina</b>.',
'retina':'The inner tunic. Its parts are pars optica (light-sensitive), pars ciliaris and pars iridica.',
'pars optica retinae':'The <b>light-sensitive</b> part of the retina, behind the ora serrata.',
'pars ciliaris retinae':'The non-sensory retina lining the <b>ciliary body</b>.',
'pars iridica retinae':'The non-sensory retina lining the <b>back of the iris</b>.',
'dilator pupillae':'The intrinsic iris muscle that <b>widens the pupil</b>. It is sympathetic.',
'optic disk':'Where the <b>optic nerve leaves the eye</b>. There are no photoreceptors there (the blind spot).',
'external jugular vein':'The big superficial neck vein formed by the <b>linguofacial + maxillary veins</b>. Blood-draw and catheter site.',
'lingual vein':'Drains the <b>tongue</b> and joins the facial vein to form the linguofacial vein.',
'linguofacial vein':'Formed by the <b>lingual + facial veins</b>. It joins the maxillary vein to form the external jugular.',
'facial vein':'Runs across the <b>side of the face</b> from the medial eye corner; it joins the lingual vein.',
'dorsal nasal vein':'Runs along the <b>top of the muzzle</b> into the facial vein.',
'angularis oculi vein':'Drains the <b>medial corner of the eye</b> into the facial vein.',
'deep facial vein':'A deep tributary of the facial vein, coming from <b>under the zygomatic arch</b>.',
'maxillary vein':'Comes from behind the mandible and joins the linguofacial vein to form the <b>external jugular</b>.',
'facial (seventh cranial) nerve':'<b>CN VII</b> leaves the <b>stylomastoid foramen</b>. Its branches (auriculopalpebral, dorsal and ventral buccal) supply the muscles of facial expression.',
'auriculopalpebral nerve':'A facial nerve branch to the <b>ear muscles and eyelids</b> (blinking).',
'rostral auricular branches':'Auriculopalpebral branches to the <b>rostral ear muscles</b>.',
'palpebral branches':'Auriculopalpebral branches to the <b>orbicularis oculi</b> (closing the eyelids).',
'buccal branches':'The <b>dorsal + ventral buccal branches</b> of the facial nerve, running across the masseter to the lips and cheek.',
'dorsal buccal branch':'The upper buccal branch of CN VII, running <b>across the masseter</b>. The auriculotemporal nerve rides with it.',
'ventral buccal branch':'The lower buccal branch of CN VII, along the <b>ventral masseter</b>.',
'trigeminal (fifth cranial) nerve':'<b>CN V</b>. In this lab you only see its <b>auriculotemporal</b> branch (sensory); the trunk is inside the skull.',
'auriculotemporal nerve':'A <b>V3 sensory</b> branch that rides with the dorsal buccal branch of CN VII.',
'thyroid gland':'The 2 lobes on the <b>lateral sides of the trachea</b>, near tracheal rings 5–8.',
'parathyroid glands':'4 small glands: one <b>external</b> and one <b>internal</b> on each thyroid lobe.',
'external parathyroid':'The parathyroid on the <b>cranial, outer surface</b> of the thyroid lobe.',
'internal parathyroid':'The parathyroid <b>embedded inside</b> the thyroid lobe.',
'cervical portion of the esophagus':'The neck part of the esophagus, <b>dorsal then left of the trachea</b>.',
'pharyngoesophageal limen':'The <b>boundary between the laryngopharynx and the esophagus</b>.',
'trachea':'The airway down the neck, held open by C-shaped cartilages; the trachealis muscle closes them dorsally.',
'tracheal cartilages':'The <b>C-shaped rings</b>, open dorsally, that keep the trachea from collapsing.',
}
build(31,'Eye + superficial head',S)
